begin;
alter policy own_work_sites on public.staff_site_assignments using(org_id=app.org_id() and staff_member_id=app.phase2_staff_id());
grant execute on function app.packet_documents_view(uuid),app.advocate_view_identity(uuid) to authenticated;
do $$
declare o uuid:='10000000-0000-4000-8000-000000000001'; site uuid:='10000000-0000-4000-8000-000000000002'; u uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); pu uuid:=gen_random_uuid(); pa uuid:=gen_random_uuid(); au uuid:=gen_random_uuid(); aa uuid:=gen_random_uuid(); adv uuid:=gen_random_uuid(); p uuid:=md5('phase2b:patient:d4bzjiw8')::uuid; ref uuid:=md5('phase2b:referral:lc4w2pi3')::uuid; c uuid; link uuid; j jsonb; n int; sess uuid;
begin
insert into auth.users(id,aud,role,email) values(u,'authenticated','authenticated','phase2c-multi@example.test'),(pu,'authenticated','authenticated','phase2c-patient@example.test'),(au,'authenticated','authenticated','phase2c-advocate@example.test');
insert into public.accounts(id,org_id,auth_user_id,kind,synthetic) values(a,o,u,'staff',true),(pa,o,pu,'patient',true),(aa,o,au,'advocate',true);
insert into public.staff_members(id,org_id,account_id,source_key,name,synthetic) values(m,o,a,'phase2c-multi','Fictional Multi-role',true);
insert into public.staff_role_assignments(org_id,staff_member_id,role,is_primary) values(o,m,'intake_coordinator',true),(o,m,'therapist',false);
insert into public.staff_site_assignments(org_id,staff_member_id,site_id,starts_at,synthetic) values(o,m,site,now()-interval '1 day',true);
perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true); perform app.attest_beta('en'); perform app.set_acting_role('intake_coordinator');
update public.intake_checklists set completed_at=null where referral_id=ref;
set local role authenticated;
select count(*) into n from public.staff_site_assignments; if n<>1 then raise exception 'own_sites_sibling_leak'; end if;
j:=app.packet_documents_view(ref); if jsonb_array_length(j)<>4 or (select count(*) from jsonb_array_elements(j) d where (d->>'locked')::boolean)<>2 then raise exception 'packet_seed_lock'; end if;
if exists(select 1 from jsonb_array_elements(j) d where (d->>'locked')::boolean and (d ? 'file_name' or d ? 'source' or d ? 'document_type')) then raise exception 'locked_metadata_leak'; end if;
if (app.chart_entry(p)->>'ok')::boolean then raise exception 'intake_chart_leak'; end if;
reset role;
insert into public.consent_records(org_id,patient_id,consent_type,recipients,purpose_code,items,status,effective_at,signed_at,signed_by_kind,signature_method,part2_elements,synthetic) values(o,p,'part2_tpo_single','[{"kind":"class","name":"Adelante care team","directoryRef":"adelante-program"}]','tpo',array['Intake and treatment information'],'active',now(),now(),'staff_capture','e_sign','{"patientName":true,"recipients":true,"amountAndKind":true,"purpose":true,"rightToRevoke":true,"expiration":true,"signatureAndDate":true,"redisclosureNotice":true}',true) returning id into c;
set local role authenticated;
j:=app.packet_documents_view(ref); if exists(select 1 from jsonb_array_elements(j) d where (d->>'locked')::boolean) then raise exception 'packet_consent_unlock_failed'; end if;
if exists(select 1 from app.can_access('screeners_sud',p) where level<>'none') or exists(select 1 from app.can_access('sud_treatment',p) where level<>'none') then raise exception 'intake_matrix_widened'; end if;
reset role; update public.consent_records set status='revoked' where id=c;
set local role authenticated; j:=app.packet_documents_view(ref); if (select count(*) from jsonb_array_elements(j) d where (d->>'locked')::boolean)<>2 then raise exception 'revoke_relock_failed'; end if;
reset role;
perform app.set_acting_role('therapist');
set local role authenticated; if app.current_role()<>'therapist' or app.phase2_intake(ref,true) then raise exception 'held_role_union'; end if;
reset role;
insert into public.restricted_record_flags(org_id,patient_id,reason_code,synthetic) values(o,p,'fictional_restriction',true);
set local role authenticated; if (app.chart_entry(p)->>'ok')::boolean then raise exception 'restricted_without_reason'; end if;
reset role;
select id into sess from public.acting_role_sessions where account_id=a and ended_at is null;
insert into public.restricted_record_opens(org_id,patient_id,account_id,acting_session_id,reason_code,synthetic) values(o,p,a,sess,'fictional_review',true);
set local role authenticated; if not (app.chart_entry(p)->>'ok')::boolean then raise exception 'reasoned_open_denied'; end if;
reset role; perform app.set_acting_role('intake_coordinator');
set local role authenticated; if (app.chart_entry(p)->>'ok')::boolean then raise exception 'open_survived_role_switch'; end if;
reset role;
update public.restricted_record_flags set active=false where patient_id=p and reason_code='fictional_restriction';
update public.patients set account_id=pa where id=p;
perform set_config('request.jwt.claims',jsonb_build_object('sub',pu,'role','authenticated')::text,true); perform app.attest_beta('en');
set local role authenticated; select count(*) into n from public.patients; if n<>1 or not app.owns_patient(p) then raise exception 'patient_ownership_leak'; end if; reset role;
insert into public.advocates(id,org_id,account_id,name,synthetic) values(adv,o,aa,'Fictional Advocate',true);
insert into public.consent_records(org_id,patient_id,consent_type,recipients,purpose_code,items,status,effective_at,signed_at,signed_by_kind,signature_method,part2_elements,synthetic) values(o,p,'advocate_release',jsonb_build_array(jsonb_build_object('directoryRef',adv::text)),'care_coordination',array['demographics'],'active',now(),now(),'patient','e_sign','{"patientName":true,"recipients":true,"amountAndKind":true,"purpose":true,"rightToRevoke":true,"expiration":true,"signatureAndDate":true,"redisclosureNotice":true}',true) returning id into c;
insert into public.advocate_links(org_id,advocate_id,patient_id,scope,consent_record_id,status,synthetic) values(o,adv,p,array['demographics'],c,'active',true) returning id into link;
perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated')::text,true); perform app.attest_beta('en');
set local role authenticated; j:=app.advocate_view_identity(link); if j->>'id'<>p::text or j ? 'locked' then raise exception 'advocate_consented_slice_denied'; end if; select count(*) into n from public.patients; if n<>0 then raise exception 'advocate_direct_row_leak'; end if; reset role;
update public.consent_records set status='revoked' where id=c;
set local role authenticated; j:=app.advocate_view_identity(link); if j<>jsonb_build_object('id',link,'locked',true,'reason','Advocate link and consent required') then raise exception 'advocate_revoke_leak'; end if; reset role;
-- Store-derived packet chain checked structurally, not as an unported write transport.
if not exists(select 1 from public.staging_rows s join public.packet_documents d on d.referral_id=s.referral_id join public.referrals r on r.id=s.referral_id join public.patients pt on pt.id=r.linked_patient_id join public.care_team_assignments ct on ct.patient_id=pt.id join public.first_visit_handoffs h on h.patient_id=pt.id and h.referral_id=r.id where r.id=ref) then raise exception 'seed_packet_chain_missing'; end if;
end $$;
rollback;